-- -----------------------------------------------------------------------------------
-- 2. LIMPIEZA DE TRANSACCIONES OPERACIONALES
-- -----------------------------------------------------------------------------------
TRUNCATE TABLE `canjes`;
TRUNCATE TABLE `ecopuntos`;
TRUNCATE TABLE `entregas`;
TRUNCATE TABLE `recolecciones`;
TRUNCATE TABLE `solicitudes`;

SET FOREIGN_KEY_CHECKS = 1;

-- -----------------------------------------------------------------------------------
-- 3. INSERCIÓN DE TRANSACCIONES HISTÓRICAS OPERATIVAS (SOLICITUDES, ENTREGAS, PUNTOS, CANJES)
-- -----------------------------------------------------------------------------------


















































































































































-- ===================================================================================
-- VISTA DEL DICCIONARIO DE DATOS MENSUAL (HOMOLOGACIÓN PARA MINERÍA DE DATOS)
-- ===================================================================================
CREATE OR REPLACE VIEW `vw_diccionario_ecopoints_mensual` AS
WITH 
    cte_materiales_mes AS (
        SELECT 
            e.id_reciclador AS reciclador_id,
            CAST(DATE_FORMAT(e.fecha_entrega, '%Y-%m-01') AS DATE) AS mes,
            m.nombre AS material,
            SUM(e.cantidad_validada) AS kg_material,
            ROW_NUMBER() OVER (
                PARTITION BY e.id_reciclador, CAST(DATE_FORMAT(e.fecha_entrega, '%Y-%m-01') AS DATE)
                ORDER BY SUM(e.cantidad_validada) DESC, COUNT(e.id_entrega) DESC, m.nombre ASC
            ) AS rn
        FROM entregas e
        INNER JOIN recolecciones r ON e.id_recoleccion = r.id_recoleccion
        INNER JOIN solicitudes s ON r.id_solicitud = s.id_solicitud
        INNER JOIN materiales m ON s.id_material = m.id_material
        WHERE e.estado = 'Validada'
        GROUP BY e.id_reciclador, CAST(DATE_FORMAT(e.fecha_entrega, '%Y-%m-01') AS DATE), m.nombre
    ),
    cte_entregas_mes AS (
        SELECT 
            e.id_reciclador AS reciclador_id,
            CAST(DATE_FORMAT(e.fecha_entrega, '%Y-%m-01') AS DATE) AS mes,
            ROUND(SUM(e.cantidad_validada), 2) AS kg_recolectados,
            COUNT(DISTINCT e.id_entrega) AS entregas,
            COUNT(DISTINCT s.id_material) AS diversidad_materiales
        FROM entregas e
        INNER JOIN recolecciones r ON e.id_recoleccion = r.id_recoleccion
        INNER JOIN solicitudes s ON r.id_solicitud = s.id_solicitud
        WHERE e.estado = 'Validada'
        GROUP BY e.id_reciclador, CAST(DATE_FORMAT(e.fecha_entrega, '%Y-%m-01') AS DATE)
    ),
    cte_puntos_mes AS (
        SELECT 
            ep.id_reciclador AS reciclador_id,
            CAST(DATE_FORMAT(ep.fecha_generacion, '%Y-%m-01') AS DATE) AS mes,
            SUM(ep.cantidad_puntos) AS puntos_obtenidos
        FROM ecopuntos ep
        WHERE ep.estado = 'activo'
        GROUP BY ep.id_reciclador, CAST(DATE_FORMAT(ep.fecha_generacion, '%Y-%m-01') AS DATE)
    ),
    cte_canjes_mes AS (
        SELECT 
            c.id_usuario AS reciclador_id,
            CAST(DATE_FORMAT(c.fecha_canje, '%Y-%m-01') AS DATE) AS mes,
            COUNT(c.id_canje) AS beneficios_redimidos
        FROM canjes c
        WHERE c.estado IN ('generado', 'reclamado')
        GROUP BY c.id_usuario, CAST(DATE_FORMAT(c.fecha_canje, '%Y-%m-01') AS DATE)
    ),
    cte_resumen_mensual AS (
        SELECT 
            em.reciclador_id,
            em.mes,
            COALESCE(mp.material, 'Varios') AS material_principal,
            em.kg_recolectados,
            em.entregas,
            em.diversidad_materiales,
            COALESCE(cm.beneficios_redimidos, 0) AS beneficios_redimidos,
            COALESCE(pm.puntos_obtenidos, 0) AS puntos_obtenidos
        FROM cte_entregas_mes em
        LEFT JOIN cte_materiales_mes mp ON em.reciclador_id = mp.reciclador_id AND em.mes = mp.mes AND mp.rn = 1
        LEFT JOIN cte_puntos_mes pm ON em.reciclador_id = pm.reciclador_id AND em.mes = pm.mes
        LEFT JOIN cte_canjes_mes cm ON em.reciclador_id = cm.reciclador_id AND em.mes = cm.mes
    )
SELECT 
    CAST(crm.reciclador_id AS SIGNED) AS reciclador_id,
    CAST(crm.mes AS DATE) AS mes,
    CAST(crm.material_principal AS CHAR(60) CHARACTER SET utf8mb4) AS material_principal,
    CAST(crm.kg_recolectados AS DECIMAL(10,2)) AS kg_recolectados,
    CAST(crm.entregas AS SIGNED) AS entregas,
    CAST(crm.diversidad_materiales AS SIGNED) AS diversidad_materiales,
    CAST(crm.beneficios_redimidos AS SIGNED) AS beneficios_redimidos,
    CAST(crm.puntos_obtenidos AS DECIMAL(10,2)) AS puntos_obtenidos,
    CAST(LEAD(crm.puntos_obtenidos, 1) OVER (PARTITION BY crm.reciclador_id ORDER BY crm.mes ASC) AS DECIMAL(10,2)) AS puntos_mes_siguiente
FROM cte_resumen_mensual crm;
